import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  interpolateColors,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type AIChatInputProps = Record<string, any>;

const AIChatInput: React.FC<AIChatInputProps> = ({
  backgroundColor = "#f0f2f5",
  transparentBackground = false,
  durationInSeconds = 8,
  boxColor = "#ffffff",
  textColor = "#1f2937",
  accentColor = "#3b82f6",
  inactiveIconColor = "#9ca3af",
  inputText = "Write a poem about the ocean...",
  placeholderText = "Animate anything...",
  typingSpeed = 3,
  scale = 1.0,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background Logic
  const finalBgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Timing Config ---
  const entryDuration = 25;
  const startTypingFrame = 45;
  const totalChars = inputText.length;
  const typingDuration = totalChars * typingSpeed;
  const finishTypingFrame = startTypingFrame + typingDuration;

  // --- Animations ---

  // 1. Entry Animation (Spring)
  const entryScale = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 },
    durationInFrames: entryDuration,
  });

  const entryOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // 2. Typing Logic
  const charProgress = interpolate(
    frame,
    [startTypingFrame, finishTypingFrame],
    [0, totalChars],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  
  const currentText = inputText.slice(0, Math.floor(charProgress));
  const isTypingFinished = frame >= finishTypingFrame;
  const isTypingStarted = frame >= startTypingFrame;

  // 3. Cursor Blinking
  const cursorOpacity = Math.sin(frame / 5) > 0 ? 1 : 0;

  // 4. Send Icon Animation
  // Interpolate color from inactive to active once typing finishes
  const iconColor = interpolateColors(
    frame,
    [finishTypingFrame, finishTypingFrame + 15],
    [inactiveIconColor, accentColor]
  );

  // Pop effect for the icon when it becomes active
  const iconScale = spring({
    frame: frame - finishTypingFrame,
    fps,
    config: { damping: 10, stiffness: 200 },
    durationInFrames: 20,
  });
  
  // Ensure icon scale is 1 before the pop
  const finalIconScale = frame < finishTypingFrame ? 1 : iconScale;

  // Placeholder Opacity: Fade out when typing starts
  const placeholderOpacity = interpolate(
    frame,
    [startTypingFrame, startTypingFrame + 10],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Layout Constants (Updated for larger size)
  const containerWidth = Math.min(width * 0.8, 1200); // Increased max width
  const containerHeight = 100 * scale; // Increased base height
  const fontSize = 32 * scale; // Increased font size
  const borderRadius = 50 * scale; // Increased border radius
  const padding = 40 * scale; // Increased padding

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Inter",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          width: containerWidth,
          minHeight: containerHeight,
          backgroundColor: boxColor,
          borderRadius: borderRadius,
          boxShadow: "0 6px 30px rgba(0,0,0,0.1)",
          border: "1px solid rgba(0,0,0,0.05)",
          display: "flex",
          alignItems: "center",
          padding: `0 ${padding}px`,
          transform: `scale(${entryScale})`,
          opacity: entryOpacity,
          position: "relative",
          transition: "none",
        }}
      >
        {/* Text Container */}
        <div
          style={{
            flex: 1,
            display: "flex",
            alignItems: "center",
            height: "100%",
            fontSize: fontSize,
            color: textColor,
            overflow: "hidden",
            whiteSpace: "nowrap",
            position: "relative",
            transition: "none",
          }}
        >
          {/* Placeholder */}
          {!isTypingStarted && (
             <span
               style={{
                 position: "absolute",
                 left: 0,
                 color: inactiveIconColor,
                 opacity: placeholderOpacity,
                 transition: "none",
               }}
             >
               {placeholderText}
             </span>
          )}

          {/* Active Text */}
          <span style={{ transition: "none" }}>
            {currentText}
          </span>

          {/* Cursor */}
          <span
            style={{
              display: "inline-block",
              width: 4 * scale,
              height: fontSize * 1.2,
              backgroundColor: accentColor,
              marginLeft: 4 * scale,
              opacity: cursorOpacity,
              transition: "none",
              verticalAlign: "middle",
            }}
          />
        </div>

        {/* Send Icon Container */}
        <div
          style={{
            width: 60 * scale,
            height: 60 * scale,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            marginLeft: 16 * scale,
            transition: "none",
          }}
        >
          <svg
            width={32 * scale}
            height={32 * scale}
            viewBox="0 0 24 24"
            fill="none"
            stroke={iconColor}
            strokeWidth="2.5"
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{
              transform: `scale(${finalIconScale})`,
              transition: "none",
            }}
          >
            <line x1="22" y1="2" x2="11" y2="13"></line>
            <polygon points="22 2 15 22 11 13 2 9 22 2"></polygon>
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default AIChatInput;